@Override
@Transactional(readOnly = true)
public Collection<Vet> findVets() throws DataAccessException {
    return vetRepository.findAll();
}

@Override
@Transactional
public void saveOwner(Owner owner) throws DataAccessException {
    if (owner.isNew() && isDuplicateEmail(owner)) {
        throw new DuplicateOwnerException(
            "An owner with the same email already exists");
    }
    if (owner.isNew() && isDuplicateTelephone(owner)) {
        throw new DuplicateOwnerException(
            "An owner with the same telephone already exists");
    }
    if (owner.isNew() && isDuplicateOwner(owner)) {
        throw new DuplicateOwnerException(
            "An owner with the same last name and telephone already exists");
    }
    if (owner.getRegistrationDate() == null) {
        owner.setRegistrationDate(LocalDate.now());
    }
    if (owner.isNew() && dailyRegistrationLimitReached(owner.getRegistrationDate())) {
        throw new DailyOwnerRegistrationLimitExceededException(
            "The maximum number of owners that can be registered today has been reached");
    }
    ownerRepository.save(owner);

}

private boolean isDuplicateEmail(Owner owner) {
    if (owner.getEmail() == null) {
        return false;
    }
    String email = normalizeKey(owner.getEmail());
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> !existing.getId().equals(owner.getId())
            && Objects.equals(normalizeKey(existing.getEmail()), email));
}

private boolean isDuplicateTelephone(Owner owner) {
    if (owner.getTelephone() == null) {
        return false;
    }
    String telephone = normalizeKey(owner.getTelephone());
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> !existing.getId().equals(owner.getId())
            && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
}

/**
 * The maximum number of owners that may be registered on a single calendar day (by registration
 * date). Attempts to register more than this in a day are rejected.
 */
private static final long MAX_OWNERS_PER_DAY = 20;

private boolean dailyRegistrationLimitReached(LocalDate registrationDate) {
    if (registrationDate == null) {
        return false;
    }
    long registeredOnDay = ownerRepository.findAll().stream()
        .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
        .count();
    return registeredOnDay >= MAX_OWNERS_PER_DAY;
}

private boolean isDuplicateOwner(Owner owner) {
    if (owner.getLastName() == null) {
        return false;
    }
    String lastName = normalizeKey(owner.getLastName());
    String telephone = normalizeKey(owner.getTelephone());
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> !existing.getId().equals(owner.getId())
            && Objects.equals(normalizeKey(existing.getLastName()), lastName)
            && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
}

/**
 * Normalizes a value for duplicate detection so that comparisons ignore
 * letter case and surrounding or repeated whitespace (e.g. {@code
 * "  john   smith "} and {@code "John Smith"} are treated as equal).
 */
private static String normalizeKey(String value) {
    if (value == null) {
        return null;
    }
    return value.trim().replaceAll("\\s+", " ").toLowerCase();
}

@Override
@Transactional(readOnly = true)
public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
    return ownerRepository.findByLastName(lastName);
}

@Override
@Transactional(readOnly = true)
public Collection<Visit> findVisitsByPetId(int petId) {
    return visitRepository.findByPetId(petId);
}

@Override
@Transactional(readOnly = true)
public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
    return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
}

private <T> T findEntityById(Supplier<T> supplier) {
    try {
        return supplier.get();
    } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
        // Just ignore not found exceptions for Jdbc/Jpa realization
        return null;
    }

